<script setup lang="ts">
import { computed,onMounted,onUnmounted,ref } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { ElMessage,ElMessageBox } from 'element-plus'
import InspectionCoveragePanel from '../components/InspectionCoveragePanel.vue'
import { inspectionFindings } from '../utils/inspection-status'
import { cancelInspection,downloadInspection,getInspection,getInspectionTarget,reconcileInspection,regenerateInspectionReports,type InspectionCoverage,type InspectionResult,type InspectionRun,type InspectionTarget } from '../api/operations'
const route=useRoute(),router=useRouter(),id=Number(route.params.id),run=ref<InspectionRun>(),targets=ref<InspectionTarget[]>([]),error=ref(''),busy=ref(false),selected=ref<number>(),result=ref<InspectionResult>(),targetError=ref(''),detailVisible=ref(false),coverage=ref<InspectionCoverage>()
const findings=computed(()=>run.value?inspectionFindings(run.value,coverage.value?.summary):{warning:0,critical:0,recorded:0})
const active=computed(()=>['QUEUED','RUNNING'].includes(run.value?.status||'')),progress=computed(()=>run.value?.totalTargets?Math.round(run.value.completedTargets/run.value.totalTargets*100):0)
const label=(s:string)=>({NORMAL:'正常',WARNING:'告警',CRITICAL:'严重',UNKNOWN:'未取得完整结果',NOT_APPLICABLE:'不适用',RECORDED:'已记录待核对',QUEUED:'等待下发',RUNNING:'执行中',COMPLETED:'已完成',PARTIAL:'检查已结束',FAILED:'失败',CANCELED:'已取消',READY:'已生成',PENDING:'等待生成',GENERATING:'生成中'}[s]||s)
const tag=(s:string)=>['NORMAL','COMPLETED','READY'].includes(s)?'success':['FAILED','CRITICAL'].includes(s)?'danger':['WARNING','PARTIAL','UNKNOWN'].includes(s)?'warning':'info'
const time=(s:string|null|undefined)=>s?new Date(s).toLocaleString('zh-CN',{hour12:false}):'-'
async function refresh(){if(busy.value)return;busy.value=true;try{const data=await getInspection(id);run.value=data.run;targets.value=data.targets;coverage.value=data.coverage;error.value=''}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function show(row:InspectionTarget){selected.value=row.id;result.value=undefined;targetError.value='';detailVisible.value=true;try{const full=await getInspectionTarget(id,row.id);if(full.resultJSON)result.value=JSON.parse(full.resultJSON);else targetError.value=full.message||'尚未回收检查结果'}catch(e:any){targetError.value=e.message}}
async function cancel(){await ElMessageBox.confirm('发送取消请求？远端执行器确认结束后才会标记为已取消。','取消巡检',{type:'warning'});await cancelInspection(id);await refresh()}
async function regenerate(){await regenerateInspectionReports(id);ElMessage.success('已开始重新生成报告，不会重新执行服务器检查');await refresh()}
async function reconcile(){await reconcileInspection(id);ElMessage.success('正在核实原远端任务，不重复下发');await refresh()}
async function download(){try{await downloadInspection(id)}catch(e:any){ElMessage.error(e.message)}}
let timer:ReturnType<typeof setInterval>|undefined
onMounted(async()=>{await refresh();timer=setInterval(refresh,3000)})
onUnmounted(()=>{if(timer)clearInterval(timer)})
</script>
<template><div class="inspection-detail"><div class="heading"><div><el-button text @click="router.push('/inspections')">← 巡检报告</el-button><h3>系统巡检报告 <small>#{{id}}</small></h3><p v-if="run" class="muted">任务名称：{{run.name}}</p></div><div><el-button :loading="busy" @click="refresh">刷新</el-button><el-button v-if="active&&!run?.cancelRequested" type="warning" @click="cancel">取消任务</el-button><el-button v-if="!active&&targets.some(t=>t.status==='UNKNOWN')" @click="reconcile">核实远端结果</el-button><el-button v-if="!active" @click="regenerate">重新生成报告</el-button><el-button :disabled="run?.htmlStatus!=='READY'" @click="router.push(`/inspections/${id}/report`)">在线查看</el-button><el-button type="primary" :disabled="run?.pdfStatus!=='READY'" @click="download">下载 PDF</el-button></div></div><el-alert v-if="error" :title="error" type="error" :closable="false"/>
<template v-if="run"><div class="progress-card"><div class="progress-title"><el-tag :type="tag(run.status)">{{coverage?.executionLabel||label(run.status)}}</el-tag><span v-if="active">{{run.message}}</span><span class="count">已处理 {{run.completedTargets}} / {{run.totalTargets}} 个对象</span></div><el-progress :percentage="progress" :status="run.status==='COMPLETED'?'success':undefined"/><p v-if="run.cancelRequested" class="warning">取消请求已提交，正在核实远端执行状态。</p><div class="meta">发起人 {{run.operator}} · {{run.trigger==='SCHEDULED'?'定时计划':'手工触发'}} · 开始 {{time(run.startedAt)}} · 结束 {{time(run.finishedAt)}}</div></div><div class="summary"><div>运行告警 <strong>{{findings.warning}}</strong></div><div>严重问题 <strong>{{findings.critical}}</strong></div><div>已记录待判读 <strong>{{findings.recorded}}</strong></div><div>在线报告 <el-tag :type="tag(run.htmlStatus)">{{label(run.htmlStatus)}}</el-tag> PDF <el-tag :type="tag(run.pdfStatus)">{{label(run.pdfStatus)}}</el-tag></div></div><el-alert v-if="run.reportError" :title="run.reportError" type="error" :closable="false"/>
<InspectionCoveragePanel :run="run" :coverage="coverage"/><div class="content"><el-table :data="targets" size="small"><el-table-column label="巡检对象" min-width="190"><template #default="{row}"><strong>{{row.name}}</strong><div class="muted">{{row.endpoint}}</div></template></el-table-column><el-table-column label="执行主机" min-width="180"><template #default="{row}">{{row.serverEndpoint}}</template></el-table-column><el-table-column label="对象执行状态" width="140"><template #default="{row}"><el-tag :type="tag(row.status)" size="small">{{row.status==='COMPLETED'?'执行已结束':label(row.status)}}</el-tag></template></el-table-column><el-table-column prop="stage" label="当前阶段" width="155"/><el-table-column prop="message" label="结果／错误" min-width="250" show-overflow-tooltip/><el-table-column label="最近进度" width="170"><template #default="{row}">{{time(row.heartbeatAt)}}</template></el-table-column><el-table-column width="95"><template #default="{row}"><el-button text type="primary" @click="show(row)">检查详情</el-button></template></el-table-column></el-table></div><p class="muted">执行状态与检查结果分开记录。任务完成可以包含告警；采集失败、权限不足或未接入日志会明确列为未知。报告重生成只使用已保存的检查结果。</p></template>
<el-dialog v-model="detailVisible" title="检查结果与证据" width="85%"><el-alert v-if="targetError" :title="targetError" type="warning" :closable="false"/><template v-if="result"><div class="meta">执行器 {{result.version}} · 主机 {{result.hostname}} · {{time(result.startedAt)}} ～ {{time(result.finishedAt)}}</div><el-alert v-if="result.error" :title="result.error" type="error" :closable="false"/><div v-for="check in result.reportChecks" :key="check.code" class="check"><h4><el-tag :type="tag(check.status)" size="small">{{label(check.status)}}</el-tag> {{check.code}} · {{check.name}}</h4><p>{{check.value}}</p><p v-if="check.reason">{{check.reason}}</p><p v-for="gap in check.gaps" :key="gap" class="error-text">{{gap}}</p><div v-for="(entry,i) in check.executions" :key="i"><p class="muted">{{entry.kind}} · {{time(entry.startedAt)}} ～ {{time(entry.finishedAt)}} · 退出码 {{entry.exitCode}}</p><pre>{{entry.command}}</pre><strong>标准输出</strong><pre>{{entry.stdout||'（无输出）'}}</pre><pre v-if="entry.stderr" class="error-text">标准错误：{{entry.stderr}}</pre><p v-if="entry.error" class="error-text">执行错误：{{entry.error}}</p><p v-if="entry.truncated" class="error-text">输出已截断，不能视为完整结果。</p></div></div><div v-for="(check,i) in result.checks" :key="`${check.code}-${i}`" class="check"><h4><el-tag :type="tag(check.status)" size="small">{{label(check.status)}}</el-tag> {{check.name}}</h4><p>{{check.value}}</p><pre v-if="check.evidence">{{check.evidence}}</pre><pre v-if="check.error" class="error-text">{{check.error}}</pre><p v-if="check.advice" class="muted">建议：{{check.advice}}</p></div></template></el-dialog></div></template>
<style scoped>.inspection-detail{display:flex;flex-direction:column;gap:16px}.heading{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.heading h3{margin:6px 0}.heading small{color:#7c8b9d;font-size:13px;font-weight:400}.progress-card,.content{padding:20px;background:#fff;border:1px solid #e2e8f0;border-radius:7px}.progress-title{display:flex;gap:12px;align-items:center;font-size:13px;margin-bottom:16px}.count{margin-left:auto;color:#708198}.meta,.muted{font-size:12px;color:#78899c;line-height:1.8}.meta{margin-top:12px}.summary{display:grid;grid-template-columns:1fr 1fr 1fr 2fr;gap:14px}.summary>div{padding:18px;background:#fff;border:1px solid #e2e8f0;border-radius:7px;font-size:12px;color:#6c7c90}.summary strong{font-size:24px;margin-left:12px;color:#253f60}.summary .el-tag{margin:0 12px 0 5px}.check{padding:15px 0;border-bottom:1px solid #e2e8f0}.check h4{margin:0;font-size:13px}.check p{font-size:13px;line-height:1.8}.warning{color:#b07b20;font-size:12px}pre{white-space:pre-wrap;overflow-wrap:anywhere;word-break:break-word;background:#f6f8fb;padding:12px;font-size:12px;line-height:1.7;max-height:400px;overflow:auto;border:1px solid #e2e8f0}.error-text{color:#b23d3d}@media(max-width:1000px){.summary{grid-template-columns:1fr 1fr}.heading>div:last-child{display:flex;flex-wrap:wrap;gap:8px}}</style>
